proc sql noprint;
  create table x4 as select distinct a.*, b.DATADATE as DATADATE_L1, b.RDQ as RDQ_L1, 
  b.IBQ as IBQ_L1, b.SALEQ as SALEQ_L1, b.BVEQ as BVEQ_L1, b.MVEQ as MVEQ_L1, b.ATQ as ATQ_L1, b.DEBTQ as DEBTQ_L1 from
