*DOWNLOAD DAILY STOCK RETURN DATA;
*keep public refineries;
data x1;
set REFINERY.orbital_new;
  where missing(permno)=0;
  permno1=permno+0;
  keep permno1 local_date;
  rename permno1=permno local_date=date;
proc sort data=x1 nodupkey;
  by permno date;
run;


proc means data=x1 noprint;
  by permno;
  output out=x2 (drop=_type_) min(date)=min_date max(date)=max_date;
run;


data x3;
set x2;
  beg_date=intnx('month',min_date,-18,'b');
  end_date=intnx('month',max_date,+18,'e');
  format beg_date end_date mmddyy10.;
proc sort data=x3 nodupkey;
  by permno;
run;

*daily returns;
proc sql noprint;
  create table work.x2 as select distinct a.*, b.date, b.hsiccd, b.hexcd, 
  (b.ret+0) as ret, abs(b.prc) as prc, b.shrout from
  work.x1 as a, CRSP.dsf as b
  where a.permno=b.permno & a.beg_date<=b.date<=a.end_date

*delisting codes & delisting returns;
proc sql noprint;
  create table work.x3 as select distinct a.*, b.dlstcd, b.dlret from
  work.x2 as a left join CRSP.dsedelist as b
  on a.permno=b.permno & a.date=b.dlstdt
  order by permno, date;
quit;

*incorporate market Return;
proc sql noprint;
  create table work.x4 as select distinct a.*, b.* from
  work.x3 as a left join FF.factors_daily as b
  on a.date=b.date
  order by a.permno, a.date;
quit;

