quit;

proc sql noprint;
  create table y4 as select distinct a.*, b.date, b.ret, (b.mktrf+b.rf) as mkt, intck('weekday',a.rdq,b.date) as gap from
  y3 as a left join REFINERY.rr2_dsf as b
  on a.permno1=b.permno & -5<=intck('weekday',a.rdq,b.date)<=+5
  order by a.permno, a.datadate, b.date;

*daily returns;
