*future returns;
proc printto log="[redacted-path-824763d23357]"; run;
proc expand data=x4 out=x5 method=none;
  by permno; id date;
  convert mktcap=mktcap_l1 / transformout=(lag 1);
  convert ret=ret_f1 / transformout=(lead 1);
  convert ret=ret_f2 / transformout=(lead 2);
  convert ret=ret_f3 / transformout=(lead 3);
  convert ret=ret_f4 / transformout=(lead 4);
  convert ret=ret_f5 / transformout=(lead 5);
  convert ret=ret_f6 / transformout=(lead 6);
  convert ret=ret_f7 / transformout=(lead 7);
  convert ret=ret_f8 / transformout=(lead 8);
  convert ret=ret_f9 / transformout=(lead 9);
run;

data x6;
  informat permno date dateff hsiccd hexcd prc shrout mktcap mktcap_l1 rf mktrf smb hml umd ret;
set x5;
  where date>='01jan2017'd;
  ret_m1=ret_f1;
  ret_m2=exp(log(1+ret_m1)+log(1+ret_f2))-1;
  ret_m3=exp(log(1+ret_m2)+log(1+ret_f3))-1;
  ret_m4=exp(log(1+ret_m3)+log(1+ret_f4))-1;
  ret_m5=exp(log(1+ret_m4)+log(1+ret_f5))-1;
  ret_m6=exp(log(1+ret_m5)+log(1+ret_f6))-1;
  ret_m7=exp(log(1+ret_m6)+log(1+ret_f7))-1;
  ret_m8=exp(log(1+ret_m7)+log(1+ret_f8))-1;
  ret_m9=exp(log(1+ret_m8)+log(1+ret_f9))-1;
  format ret_f1-ret_f9 ret_m1-ret_m9 percent7.4;
  drop year month; rename ret=ret_m0;
proc sort data=x6 out=REFINERY.rr2_msf1 nodupkey;
  by permno date;
run;

