*bloomberg data;
data y2;
set y1;
  where missing(coordinates)=0 & missing(start)=0 & missing(end)=0;
  bbg_planned=(type='P');
  bbg_interval=intck('day',start,end);
  keep coordinates type bbg_planned start end bbg_interval;
  rename type=bbg_type start=bbg_start end=bbg_end;
